// LoadSnapshotIfExists loads a schema-checked snapshot from path when the file
// exists. It returns false, nil when path does not exist; true, nil after a
// successful load; and false plus a non-nil error for other failures, including
// snapshot.ErrFingerprintMismatch (detectable with errors.Is).
func (r *Runtime) LoadSnapshotIfExists(path string) (bool, error) {
	if err := r.LoadSnapshot(path); err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return false, nil
		}
		return false, err
	}
	return true, nil
}

// RunSnapshotAutosave periodically saves entity snapshots to path until ctx is
// cancelled. It blocks on the caller's goroutine, waits for each asynchronous
// SaveSnapshot result before starting the next save, returns the first save
// error, and returns ctx.Err() on cancellation. Cancellation that arrives while
// a save is in flight waits for that filesystem result: a failed save returns
// the save error (not ctx.Err()); a successful save then returns ctx.Err().
// A buffered/ready tick does not start a save when ctx is already cancelled
// (ctx.Err is checked immediately before invoking save). A cancellation that
// races after that pre-save check may still allow that already-starting save;
// in-flight saves are always awaited before return. It does not spawn a
// background goroutine, log, invoke callbacks, or perform an implicit final
// save — callers own concurrency and error policy:
//
//	go func() {
//		if err := rt.RunSnapshotAutosave(ctx, "world.snap", time.Minute); err != nil && !errors.Is(err, context.Canceled) {
//			log.Printf("autosave: %v", err)
//		}
//	}()
func (r *Runtime) RunSnapshotAutosave(ctx context.Context, path string, interval time.Duration) error {
	return startSnapshotAutosave(ctx, interval, func() <-chan error {
		return r.SaveSnapshot(path)
	}, time.NewTicker)
}

// startSnapshotAutosave validates ctx and interval before creating a ticker or
// invoking save, then runs the serialized autosave loop.
func startSnapshotAutosave(ctx context.Context, interval time.Duration, save func() <-chan error, newTicker func(time.Duration) *time.Ticker) error {
	if ctx == nil {
		return fmt.Errorf("snapshot: nil context")
	}
	if interval <= 0 {
		return fmt.Errorf("snapshot: autosave interval must be positive")
	}
	ticker := newTicker(interval)
	defer ticker.Stop()
	return runSnapshotAutosave(ctx, ticker.C, save)
}

// runSnapshotAutosave drives serialized snapshot saves from ticks. It is
// unexported so tests can inject a tick channel and save function without
// sleeps or hidden goroutines in the exported API.
func runSnapshotAutosave(ctx context.Context, ticks <-chan time.Time, save func() <-chan error) error {
	for {
		select {
		case <-ctx.Done():
			return ctx.Err()
		case <-ticks:
			// Prefer an already-cancelled context over a buffered/ready tick.
			if err := ctx.Err(); err != nil {
				return err
			}
			if err := <-save(); err != nil {
				return err
			}
			if err := ctx.Err(); err != nil {
				return err
			}
		}
	}
}

var (
	restoreMonsterWrapper func(*SyncedMonster) golem.Entity
	restorePlayerWrapper  func(*SyncedPlayer) golem.Entity
)

// RegisterMonsterWrapper registers a restore-time wrapper for Monster entities.
// When set, RestoreEntity returns fn(e) instead of the bare *SyncedMonster.
// Pass nil to clear the wrapper and restore the default behavior.
func RegisterMonsterWrapper(fn func(*SyncedMonster) golem.Entity) {
	restoreMonsterWrapper = fn
}

// RegisterPlayerWrapper registers a restore-time wrapper for Player entities.
// When set, RestoreEntity returns fn(e) instead of the bare *SyncedPlayer.
// Pass nil to clear the wrapper and restore the default behavior.
func RegisterPlayerWrapper(fn func(*SyncedPlayer) golem.Entity) {
	restorePlayerWrapper = fn
}

// MarshalEntityRemoved returns a serialized EntityUpdate containing an EntityRemoved payload.
func MarshalEntityRemoved(entityID int64, revision uint64) ([]byte, error) {
	msg := &EntityUpdate{
		Payload: &EntityUpdate_EntityRemoved{EntityRemoved: &EntityRemoved{EntityId: entityID, Revision: revision}},
	}
	return msg.Marshal(), nil
}

// RestoreEntity reconstructs a live entity from a snapshot record by unmarshaling
// the stored FullUpdate bytes and applying the embedded state. The returned entity
// has no owner and a clean dirty-bit mask; call server.CreateEntity to add it.
func RestoreEntity(rec snapshot.Record) (golem.Entity, error) {
	u := &EntityUpdate{}
	if err := u.Unmarshal(rec.StateData); err != nil {
		return nil, fmt.Errorf("snapshot: decoding entity %d (%s): %w", rec.EntityID, rec.TypeName, err)
	}
	switch p := u.Payload.(type) {
	case *EntityUpdate_MonsterState:
		e := &SyncedMonster{}
		e.ApplyState(p.MonsterState)
		if restoreMonsterWrapper != nil {
			return restoreMonsterWrapper(e), nil
		}
		return e, nil
	case *EntityUpdate_PlayerState:
		e := &SyncedPlayer{}
		e.ApplyState(p.PlayerState)
		if restorePlayerWrapper != nil {
			return restorePlayerWrapper(e), nil
		}
		return e, nil
	}
	return nil, fmt.Errorf("snapshot: unknown entity type %q", rec.TypeName)
}

// CommandErrorHandler receives command decode or dispatch errors from bound handlers.
type CommandErrorHandler func(sess *golem.Session, err error)

// CommandRouter decodes ClientMessage payloads, validates ownership for
// entity-targeted commands, resolves the typed entity, and dispatches to
// registered handlers.
type CommandRouter struct {
	srv    *golem.Server
	onMove func(senderID int64, entity *SyncedPlayer, cmd *MoveCommand)
}

// NewCommandRouter creates a router bound to the given server for ownership
// checks and entity lookups.
func NewCommandRouter(srv *golem.Server) *CommandRouter {
	return &CommandRouter{srv: srv}
}

// OnMove registers the handler for Move commands.
// The router resolves and type-asserts the target Player entity automatically.
func (r *CommandRouter) OnMove(fn func(senderID int64, entity *SyncedPlayer, cmd *MoveCommand)) {
	r.onMove = fn
}

// Per-entity command receiver interfaces. An entity wrapper can implement any of
// these to receive the corresponding command directly, without a registered callback.

// MoveCommandReceiver can be implemented by a wrapper embedding *SyncedPlayer
// to receive Move commands directly, without a registered router callback.
type MoveCommandReceiver interface {
	OnMoveCommand(senderID int64, cmd *MoveCommand)
}

// Dispatch decodes a serialized ClientMessage and routes it to the matching handler.
// For entity-targeted commands, ownership is validated and the entity is resolved first.
// If the entity implements the matching CommandReceiver interface, that method is called.
// Any registered callback set via On{CommandName} fires independently if set.
func (r *CommandRouter) Dispatch(senderID int64, data []byte) error {
	var msg ClientMessage
	if err := msg.Unmarshal(data); err != nil {
		return err
	}
	switch p := msg.Payload.(type) {
	case *ClientMessage_MoveCommand:
		owner, ok := r.srv.Owner(p.MoveCommand.EntityId)
		if !ok || owner != senderID {
			return nil
		}
		raw, ok := r.srv.Get(p.MoveCommand.EntityId)
		if !ok {
			return nil
		}
		provider, ok := raw.(interface{ GetSyncedPlayer() *SyncedPlayer })
		if !ok {
			return nil
		}
		entity := provider.GetSyncedPlayer()
		if receiver, ok := raw.(MoveCommandReceiver); ok {
			receiver.OnMoveCommand(senderID, p.MoveCommand)
		}
		if r.onMove != nil {
			r.onMove(senderID, entity, p.MoveCommand)
		}
	}
	return nil
}

// DispatchPacket decodes a serialized ClientPacket and routes each enclosed
// ClientMessage in FIFO order. Malformed packets or commands close the session.
func (r *CommandRouter) DispatchPacket(sess *golem.Session, data []byte) error {
	var packet ClientPacket
	if err := packet.Unmarshal(data); err != nil {
		sess.RequestCloseWithReason("")
		return err
	}
	for _, frame := range packet.Frames {
		if err := r.Dispatch(sess.ID, frame); err != nil {
			sess.RequestCloseWithReason("")
			return err
		}
	}
	return nil
}

// DispatchDatagram decodes one datagram-sized ClientMessage and routes it.
// Malformed commands close the session.
func (r *CommandRouter) DispatchDatagram(sess *golem.Session, data []byte) error {
	if err := r.Dispatch(sess.ID, data); err != nil {
		sess.RequestCloseWithReason("")
		return err
	}
	return nil
}

